// Extra dictionary entries for the Shift breakdown and the word bank (course words are included automatically).
// Row: ko | english | pos | extra surface forms (comma-separated, optional)
//   pos: n noun, v verb, a adjective/descriptive verb, adv adverb, pron, num, det, x fixed expression / interjection
// Verbs and adjectives are written in dictionary form (-다); their endings are generated by app/js/lib/morph.js.
// Check coverage after editing content: node tools/lexcheck.mjs
const rows = (t) => t.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('//')).map((l) => {
  const [ko, en, pos, forms] = l.split('|').map((x) => x.trim());
  return { ko, en, pos: pos || undefined, forms: forms ? forms.split(',').map((x) => x.trim()) : [] };
});

